const float EPSILON = 0.001;
const int STEPS = 256;
const float NEAR_PLANE = 0.0;
const float FAR_PLANE = 100.0;

// Utility

float lerp(float a, float b, float t) {
    return (1.0 - t) * a + t * b;
}

vec2 lerp(vec2 a, vec2 b, float t) {
    return (1.0 - t) * a + t * b;
}

vec3 lerp(vec3 a, vec3 b, float t) {
    return (1.0 - t) * a + t * b;
}

vec4 lerp(vec4 a, vec4 b, float t) {
    return (1.0 - t) * a + t * b;
}

vec2 angleToVec2(float theta) {
    return vec2(cos(theta), sin(theta));
}

vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Rotation matrices

mat3 rotX(float theta) {
    vec2 v = angleToVec2(theta);
    return mat3(
        vec3(  1.0,  0.0,  0.0),
        vec3(  0.0,  v.x, -v.y),
        vec3(  0.0,  v.y,  v.x)
    );
}

mat3 rotY(float theta) {
    vec2 v = angleToVec2(theta);
    return mat3(
        vec3(  v.x,  0.0,  v.y),
        vec3(  0.0,  1.0,  0.0),
        vec3( -v.y,  0.0,  v.x)
    );
}

mat3 rotZ(float theta) {
    vec2 v = angleToVec2(theta);
    return mat3(
        vec3(  v.x, -v.y,  0.0),
        vec3(  v.y,  v.x,  0.0),
        vec3(  0.0,  0.0,  1.0)
    );
}

// Transformations

vec3 screenToCameraRay(float fov, vec2 pos) {
    vec2 xy = pos - iResolution.xy / 2.0;
    float z = iResolution.y / tan(radians(fov) / 2.0);
    return normalize(vec3(xy, -z));
}


mat3 makeCameraWorldMatrix(vec3 e, vec3 c, vec3 up) {
    vec3 f = normalize(c - e);
    vec3 s = normalize(cross(f, up));
    vec3 u = cross(s, f);
    return mat3(s, u, -f);
}

// Signed Distance Functions - Primitives

struct sdfOutput {
    float signedDistance;
    vec3 diffuseColor;
    float roughness;
    float specularStrength;
};

sdfOutput sphereSDF(vec3 pos, float radius, vec3 color, float roughness, float specularStrength){
    return sdfOutput(
        length(pos) - radius, 
        color, roughness, specularStrength
    );
}

sdfOutput metaballSDF(vec3 pos, float threshold, vec3 color, float roughness, float specularStrength){
    return sdfOutput(
        (-threshold / length(pos)) + 1.0, 
        color, roughness, specularStrength
    );
}

sdfOutput boxSDF(vec3 pos, vec3 size, vec3 color, float roughness, float specularStrength){
    vec3 q = abs(pos) - size;
    return sdfOutput(
        length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0),
        color, roughness, specularStrength
    );
}

sdfOutput planeSDF(vec3 pos, vec3 normal, vec3 color, float roughness, float specularStrength){
    return sdfOutput(
        dot(pos, normal),
        color, roughness, specularStrength
    );
}

sdfOutput coneSDF(vec3 p, vec2 rh, vec3 color, float roughness, float specularStrength){
    vec2 q = rh.y*vec2(rh.x,-1.0);
    vec2 w = vec2( length(p.xz), p.y );
    vec2 a = w - q*clamp( dot(w,q)/dot(q,q), 0.0, 1.0 );
    vec2 b = w - q*vec2( clamp( w.x/q.x, 0.0, 1.0 ), 1.0 );
    float k = sign( q.y );
    float d = min(dot( a, a ),dot(b, b));
    float s = max( k*(w.x*q.y-w.y*q.x),k*(w.y-q.y)  );
    return sdfOutput(
        sqrt(d)*sign(s),
        color, roughness, specularStrength
    );
}

// Signed Distance Functions - Operations

sdfOutput unionSDF(sdfOutput a, sdfOutput b) {
    if (a.signedDistance < b.signedDistance) {
        return a;
    } else {
        return b;
    }
}

sdfOutput intersectSDF(sdfOutput a, sdfOutput b) {
    if (a.signedDistance > b.signedDistance) {
        return a;
    } else {
        return b;
    }
}

sdfOutput differenceSDF(sdfOutput a, sdfOutput b) {
    return intersectSDF(a, sdfOutput(
        -b.signedDistance,
        b.diffuseColor,
        b.roughness,
        b.specularStrength)
    );
}

sdfOutput addSDF(sdfOutput a, sdfOutput b) {
    return sdfOutput(
        a.signedDistance + b.signedDistance,
        lerp(a.diffuseColor, b.diffuseColor, 0.5),
        lerp(a.roughness, b.roughness, 0.5),
        lerp(a.specularStrength, b.specularStrength, 0.5)
    );
}

sdfOutput lerpSDF(sdfOutput a, sdfOutput b, float t) {
    return sdfOutput(
        lerp(a.signedDistance, b.signedDistance, t),
        lerp(a.diffuseColor, b.diffuseColor, t),
        lerp(a.roughness, b.roughness, t),
        lerp(a.specularStrength, b.specularStrength, t)
    );
}

sdfOutput invertSDF(sdfOutput a) {
    return sdfOutput(
        -a.signedDistance,
        a.diffuseColor,
        a.roughness,
        a.specularStrength
    );
}



// Signed Distance Functions - Scene

sdfOutput sceneSDF(vec3 samplePoint) {   
    return unionSDF(
        unionSDF(
        unionSDF(
        sphereSDF(
            samplePoint + vec3(2.0, -1.0, 0.0),
            1.0,
            vec3(0.2, 0.7, 0.1),
            0.7,
            16.0
        ),
        boxSDF(
            rotY(radians(20.0)) * rotX(radians(10.0)) * (samplePoint + vec3(-1.2, 1.0, 2.0)),
            vec3(1.0),
            vec3(0.1, 0.6, 1.0),
            0.7,
            2.0
        )),
        planeSDF(
            samplePoint + vec3(0.0, 3.0, 0.0),
            vec3(0.0, 1.0, 0.0),
            vec3(ceil((sin((rotY(radians(45.0)) * samplePoint).x * 4.0) + sin((rotY(radians(45.0)) * samplePoint).z * 4.0)) / 2.0)),
            1.0,
            16.0
        )),
        coneSDF(
            samplePoint + vec3(-3.0, -2.0, -2.0),
            vec2(0.5, 2.0),
            vec3(1.0, 0.1, 0.1),
            0.7,
            32.0
        )
    );
}

// Signed Distance Function - Calculation

vec3 calcNormal(vec3 pos) {
    return normalize(vec3(
        sceneSDF(vec3(pos.x + EPSILON, pos.y, pos.z)).signedDistance - sceneSDF(vec3(pos.x - EPSILON, pos.y, pos.z)).signedDistance,
        sceneSDF(vec3(pos.x, pos.y + EPSILON, pos.z)).signedDistance - sceneSDF(vec3(pos.x, pos.y - EPSILON, pos.z)).signedDistance,
        sceneSDF(vec3(pos.x, pos.y, pos.z + EPSILON)).signedDistance - sceneSDF(vec3(pos.x, pos.y, pos.z - EPSILON)).signedDistance
    ));
}

// Illumination

const vec3 GLOBAL_COLOR = vec3(0.0);
const vec3 CLEAR_COLOR = vec3(0.0);
const vec3 AMBIENT_COLOR = vec3(0.2);

struct light{
    vec3 position;
    vec3 color;
    float radius;
};

vec3 lightSDF(vec3 cameraRay, vec3 position, vec3 normal, vec3 diffuse, float roughness, float specularity) {
    light[] LIGHTS = light[](
        light(
            vec3(0.0, 5.0, 0.0),
            vec3(1.0),
            20.0
        )
    );
    vec3 finalColor = GLOBAL_COLOR;
    for (int i = 0; i < LIGHTS.length(); i++) {
        vec3 lightDir = normalize(LIGHTS[i].position - position);

        float diff = max(dot(normal, lightDir), 0.0);
        vec3 diffuseLight = diff * LIGHTS[i].color;

        float lightDistance = distance(position, LIGHTS[i].position); 
        vec3 reflectDir = reflect(lightDir, normal);
        float spec = pow(max(dot(cameraRay, reflectDir), 0.0), specularity);
        vec3 specularLight = roughness * spec * LIGHTS[i].color;

        float lightStrength = (1.0 - (lightDistance / LIGHTS[i].radius));
        finalColor += diffuse * (diffuseLight * lightStrength) +
            (diffuse * AMBIENT_COLOR) +
            specularLight * lightStrength;
    }

    return finalColor;
}

// Main

struct sdOutput{
    float depth;
    sdfOutput sdf;
};

sdOutput surfaceDist(vec3 camera, vec3 ray) {
    float depth = NEAR_PLANE;
    for (int i = 0; i < STEPS; i++) {
        sdfOutput sdf = sceneSDF(camera + depth * ray);
        float dist = sdf.signedDistance;
        if (dist < EPSILON) {
            return sdOutput(depth, sdf);
        }
        depth += dist;
        if (depth >= FAR_PLANE) {
            return sdOutput(FAR_PLANE, sdfOutput(0.0, vec3(0.0), 0.0, 0.0));
        }
    }
    return sdOutput(FAR_PLANE, sdfOutput(0.0, vec3(0.0), 0.0, 0.0));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(CLEAR_COLOR, 1.0);
    vec3 cameraRay = screenToCameraRay(65.0, fragCoord);
    vec3 cameraFocus = vec3(0.0, (sin(iTime / 2.0) * 1.5), 0.0);
    vec3 cameraPos = vec3(sin(iTime) * 12.0, 3.0, cos(iTime) * 12.0);
    mat3 cameraWorldMatrix = makeCameraWorldMatrix(
        cameraPos,
        -cameraFocus,
        vec3(0.0, 1.0, 0.0)
    );
    vec3 worldRay = cameraWorldMatrix * cameraRay;
    sdOutput sdOut = surfaceDist(cameraPos, worldRay);
    float d = sdOut.depth;
    vec3 hitPos = cameraPos + d * worldRay;

    if (d > FAR_PLANE - EPSILON) {
        return;
    }

    vec3 normal = calcNormal(hitPos);
    // Output to screen
    fragColor = vec4(lightSDF(worldRay, hitPos, normal, sdOut.sdf.diffuseColor, sdOut.sdf.roughness, sdOut.sdf.specularStrength), 1.0);
}
